import React from 'react';

const QuestionCard = ({ index, qa, questions, hideAnswers, onChange }) => (
  <div className="question-block" style={{ borderBottom: '1px solid #ddd', padding: '15px 0' }}>
    <label style={{ fontWeight: 'bold', display: 'block', marginBottom: '8px' }}>
      Security Question {index + 1}
    </label>
    
    <select
      value={qa.question}
      onChange={e => onChange(index, 'question', e.target.value)}
      style={{ 
        display: 'block', 
        width: '100%', 
        padding: '10px', 
        marginBottom: '10px',
        borderRadius: '4px',
        border: '1px solid #ccc'
      }}
    >
      <option value="">-- Choose a question --</option>
      {questions.map((q, i) => {
        // Handles if your JSON is ["Question 1"] or [{ "text": "Question 1" }]
        const displayText = typeof q === 'object' ? q.text || q.question : q;
        return (
          <option key={i} value={displayText}>
            {displayText}
          </option>
        );
      })}
    </select>

    <div style={{ display: 'flex', gap: '10px' }}>
      <div style={{ flex: 1 }}>
        <input
          type={hideAnswers ? "password" : "text"}
          placeholder="Answer"
          value={qa.answer}
          onChange={e => onChange(index, 'answer', e.target.value)}
          style={{ width: '100%', padding: '10px', boxSizing: 'border-box', borderRadius: '4px', border: '1px solid #ccc' }}
        />
      </div>
      
      <div style={{ flex: 1 }}>
        <input
          type={hideAnswers ? "password" : "text"}
          placeholder="Confirm Answer"
          value={qa.confirmAnswer}
          onChange={e => onChange(index, 'confirmAnswer', e.target.value)}
          style={{ 
            width: '100%', 
            padding: '10px', 
            boxSizing: 'border-box', 
            borderRadius: '4px', 
            border: qa.confirmAnswer && qa.answer !== qa.confirmAnswer ? '1px solid red' : '1px solid #ccc' 
          }}
        />
      </div>
    </div>
    
    {qa.confirmAnswer && qa.answer !== qa.confirmAnswer && (
      <span style={{ color: 'red', fontSize: '12px', marginTop: '5px', display: 'block' }}>
        * Answers do not match
      </span>
    )}
  </div>
);

export default QuestionCard;
